WITH s(a500,b500,c500) AS (SELECT replace(hex(zeroblob(500)),'00','a'),replace(hex(zeroblob(500)),'00','b'),replace(hex(zeroblob(500)),'00','c')), expected(rid,ea,eb,ec) AS (SELECT 1,a500,b500,c500 FROM s UNION ALL SELECT 2,c500,b500,a500 FROM s) SELECT e.rid, t.rowid, length(t.a), length(t.b), length(t.c), t.a=e.ea, t.b=e.eb, t.c=e.ec, (SELECT count(*) FROM t1) FROM expected AS e LEFT JOIN t1 AS t ON t.rowid=e.rid ORDER BY e.rid;